import{_ as o,a0 as l,w as p,s,I as i,x as a,a1 as e,A as t,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Android 工程師的一年 | LCTT x X-CMD","titleTemplate":false,"description":"Android 工程師的一年 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Android 工程師的一年 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Android 工程師的一年 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180514 A year as Android Engineer","title":"Android 工程師的一年","tag":"201807","desc":""},"relativePath":"201807/20180514 A year as Android Engineer.md","filePath":"[post].md"}'),f={name:"201807/20180514 A year as Android Engineer.md"};function m(u,r,b,A,g,T){const d=l("Link");return p(),s("div",null,[r[32]||(r[32]=i("h1",{id:"android-工程師的一年",tabindex:"-1"},[a("Android 工程師的一年 "),i("a",{class:"header-anchor",href:"#android-工程師的一年","aria-label":"Permalink to “Android 工程師的一年”"},"​")],-1)),r[33]||(r[33]=i("p",null,[i("img",{src:"https://cdn-images-1.medium.com/max/2000/1*tqshw1o4JZZlA1HW3Cki1Q.png",alt:""})],-1)),i("blockquote",null,[i("p",null,[r[1]||(r[1]=a("這幅妙絕的繪畫來自 ",-1)),e(d,{href:"https://medium.com/@Miqubel"},{default:t(()=>[...r[0]||(r[0]=[a("Miquel Beltran",-1)])]),_:1})])]),r[34]||(r[34]=i("p",null,"我的技術生涯，從兩年前算起。開始是 QA 測試員，一年後就轉入開發人員角色。沒怎麼努力，也沒有投入過多的個人時間。",-1)),i("p",null,[r[4]||(r[4]=a("你可以從",-1)),e(d,{href:"https://medium.com/@laramartin/how-i-took-my-first-step-in-it-6e9233c4684d"},{default:t(()=>[...r[2]||(r[2]=[a("我為何從生物學轉向技術",-1)])]),_:1}),r[5]||(r[5]=a("和我",-1)),e(d,{href:"https://medium.com/udacity/a-year-of-android-ffba9f3e40b6"},{default:t(()=>[...r[3]||(r[3]=[a("學習 Android 的一年",-1)])]),_:1}),r[6]||(r[6]=a(" 這兩篇文章中找到些隻言片語。今天，我想談談是自己是如何開始擔任 Android 開發人員這個角色、如何換公司以及作為 Android 工程師的一年所得所失。",-1))]),r[35]||(r[35]=i("h3",{id:"我的第一個職位角色",tabindex:"-1"},[a("我的第一個職位角色 "),i("a",{class:"header-anchor",href:"#我的第一個職位角色","aria-label":"Permalink to “我的第一個職位角色”"},"​")],-1)),r[36]||(r[36]=i("p",null,"我的第一個職位角色， Android 開發者，開始於一年前。我工作的這家公司，可以花一半的時間去嘗試其它角色的工作，這給我從 QA 職位轉到 Android 開發者職位創造了機會。",-1)),i("p",null,[r[11]||(r[11]=a("這一轉變歸功於我在晚上和週末投入學習 Android 的時間。我通過了 ",-1)),e(d,{href:"https://de.udacity.com/course/android-basics-nanodegree-by-google--nd803"},{default:t(()=>[...r[7]||(r[7]=[a("Android 基礎納米學位",-1)])]),_:1}),r[12]||(r[12]=a("、",-1)),e(d,{href:"https://de.udacity.com/course/android-developer-nanodegree-by-google--nd801"},{default:t(()=>[...r[8]||(r[8]=[a("Andriod 工程師納米學位",-1)])]),_:1}),r[13]||(r[13]=a("課程，也獲得了 ",-1)),e(d,{href:"https://developers.google.com/training/certification/"},{default:t(()=>[...r[9]||(r[9]=[a("Google 開發者認證",-1)])]),_:1}),r[14]||(r[14]=a("。這部分的詳細故事在",-1)),e(d,{href:"https://medium.com/udacity/a-year-of-android-ffba9f3e40b6"},{default:t(()=>[...r[10]||(r[10]=[a("這兒",-1)])]),_:1}),r[15]||(r[15]=a("。",-1))]),r[37]||(r[37]=n('<p>兩個月後，公司僱傭了另一位 QA，我轉向全職工作。挑戰從此開始！</p><p>比起給他們提供一台筆記本電腦和一個 git 賬號來説，要把某人轉變為勝任的開發角色，顯然困難重重。在這裏我解釋一下我在那段時間遇到的一些障礙：</p><h4 id="缺乏預期" tabindex="-1">缺乏預期 <a class="header-anchor" href="#缺乏預期" aria-label="Permalink to “缺乏預期”">​</a></h4><p>我面臨的第一個問題是不知道公司對我的期望。我認為他們希望我從第一天起就有交付物，雖然不會要求像那些經驗豐富的同事一樣，但也要完成一個小任務就交付。這種感覺讓我壓力山大。由於沒有明確的目標，我一直認為自己不夠好，而且是個偽劣的冒牌貨。</p><h4 id="缺乏指導" tabindex="-1">缺乏指導 <a class="header-anchor" href="#缺乏指導" aria-label="Permalink to “缺乏指導”">​</a></h4><p>在公司裏沒有導師的概念，環境也不允許我們一起工作。我們很少結對編程，因為總是在趕項目進度，公司要求我們持續交付。幸運的是，我的同事都樂於助人！無論何時我卡住或需要幫助，他們總是陪我一起解決。</p><h4 id="缺乏反饋" tabindex="-1">缺乏反饋 <a class="header-anchor" href="#缺乏反饋" aria-label="Permalink to “缺乏反饋”">​</a></h4><p>那段時間，我從來沒有得到過任何的反饋。我做的好還是壞？我應該改進些什麼？我不知道，因為我沒有得到過任何人的評論。</p><h4 id="缺乏學習氛圍" tabindex="-1">缺乏學習氛圍 <a class="header-anchor" href="#缺乏學習氛圍" aria-label="Permalink to “缺乏學習氛圍”">​</a></h4><p>我認為，為了保持常新，我們應該通過閲讀Blog文章、觀看演講、參加會議、嘗試新事物等方式持續學習。該公司在工作時間並沒有安排學習時間，不幸的是，其它開發人員告訴我這很常見。由於沒有學習時間，所以我覺得沒有資格花費哪怕十分鐘的時間來閲讀與工作相關且很有意思的Blog文章。</p><p>問題不僅在於缺乏明確的學習時間津貼，而且當我明確要求時，被拒絕了。</p><p>當我完成突擊任務時，發生了一個例子，我們已經完成了任務，因此我詢問是否可以用剩下的時間來學習 Kotlin。這個請求被拒絕了。</p><p>另外的例子是我想參加一個 Android 相關的研討會，然後被要求從帶薪年假中抽出時間。</p><h4 id="冒充者綜合徵" tabindex="-1">冒充者綜合徵 <a class="header-anchor" href="#冒充者綜合徵" aria-label="Permalink to “冒充者綜合徵”">​</a></h4><p>在這公司缺乏指導、缺乏反饋、缺乏學習氛圍，使我的開發者職業生涯的前九個月更加煎熬。我有感覺到，我內心的冒充者綜合徵與日俱增。</p><p>一個例子就是拉取代碼進行公開展示和代碼審查。有是我會請同事私下檢查我的代碼，並不想被公開拉取，向任何人展示。</p><p>其他時候，當我做代碼審查時，會花好幾分鐘盯着“批准”按紐猶豫不決，在擔心審查通過的代碼會被其他同事找出毛病。</p><p>當我在一些事上持反對意見時，由於缺乏相關知識，擔心被坐冷板凳，從來沒有大聲説出來過。</p><blockquote><p>某些時間我會請同事私下[...]檢查我的代碼，以避免被公開展示。</p></blockquote><h3 id="新的公司-新的挑戰" tabindex="-1">新的公司，新的挑戰 <a class="header-anchor" href="#新的公司-新的挑戰" aria-label="Permalink to “新的公司，新的挑戰”">​</a></h3>',20)),i("p",null,[r[17]||(r[17]=a("後來，我手邊有了個新的機會。感謝曾經和我共事的朋友，我被 ",-1)),e(d,{href:"http://babbel.com/"},{default:t(()=>[...r[16]||(r[16]=[a("Babbel",-1)])]),_:1}),r[18]||(r[18]=a(" 邀請去參加初級 Android 工程師職位的招聘流程。",-1))]),r[38]||(r[38]=n('<p>我見到了他們的團隊，同時自告奮勇的在他們辦公室主持了一次本地會議。此事讓我下定決心要申請這個職位。我喜歡公司的箴言：全民學習。其次，公司每個人都非常友善，在那兒工作看起來很愉快！但我沒有馬上申請，因為我認為自己不夠好，所以為什麼能申請呢？</p><p>還好我的朋友和搭檔推動我這樣做，他們給了我發送簡歷的力量和勇氣。過後不久就進入了面試流程。這很簡單：以很小的程序的形式來進行編碼挑戰，隨後是和團隊一起的技術面試，之後是和招聘經理間關於團隊合作的面試。</p><h4 id="招聘過程" tabindex="-1">招聘過程 <a class="header-anchor" href="#招聘過程" aria-label="Permalink to “招聘過程”">​</a></h4><p>我用周未的時間來完成編碼挑戰的項目，並在週一就立即發送過去。不久就受邀去當場面試。</p><p>技術面試是關於編程挑戰本身，我們談論了 Android 好的不好的地方、我為什麼以這種方式實現這功能，以及如何改進等等。隨後是招聘經理進行的一次簡短的關於團隊合作面試，也有涉及到編程挑戰的事，我們談到了我面臨的挑戰，我如何解決這些問題，等等。</p><p>最後，通過面試，得到 offer，我授受了!</p><p>我的 Android 工程師生涯的第一年，有九個月在一個公司，後面三個月在當前的公司。</p><h4 id="學習環境" tabindex="-1">學習環境 <a class="header-anchor" href="#學習環境" aria-label="Permalink to “學習環境”">​</a></h4><p>對我來説一個大的變化就是每兩週會和工程經理進行面對面會談。那樣，我很清楚我們的目標和方向。</p><p>在需要如何改進、需要如何提供幫助及如何尋求幫助這些事情上，我們得到持續的反饋和想法。他們除了提供內部培訓的的福利外，我還有每週學習時間的福利，可以學習任意想學的。到目前為止，我正利用這些時間來提高我的 Kotlin 和 RxJava 方面知識。</p><p>每日的大部分時間，我們也做結對編程。我的辦公桌上總是備着紙和筆，以便記下想法。我旁邊還配了第二把椅子，以方便同事就坐。😃</p><p>但是，我仍然在與冒充者綜合徵鬥爭。</p><h4 id="仍然有冒充者綜合徵" tabindex="-1">仍然有冒充者綜合徵 <a class="header-anchor" href="#仍然有冒充者綜合徵" aria-label="Permalink to “仍然有冒充者綜合徵”">​</a></h4><p>我仍然在鬥爭。例如，在做結對編程時，當我對某個話題不太清楚時，即使我的同事很有耐心的一遍一遍為我解釋，但有時我仍然還是不知道。</p><p>兩次三次後，壓力就堵到胸口。為什麼我還不知道？為什麼就那麼難理解？這種狀態讓我焦慮萬分。</p><p>我意識到我需要承認我確實不懂某個特定的主題，但第一步是要知道有這麼個概念！有時，僅僅需要的就是更多的時間、更多的練習，最終會“在大腦中完全演繹” 😃</p><p>例如，我常常為 Java 的接口類和抽象類所困擾，不管看了多少的例子，還是不能完全明白他們之間的區別。但一旦我使用後，即使還不能解釋其工作原理，也知道了怎麼使用以及什麼時候使用。</p><h4 id="自信" tabindex="-1">自信 <a class="header-anchor" href="#自信" aria-label="Permalink to “自信”">​</a></h4><p>當前公司的學習氛圍提升了我的自信心。即使我還在問很多問題，也開始如魚得水了。</p><p>經驗較少並不意味着您的意見將不會被重視。比如一個提出的解決方案似乎太複雜了，我會挑戰自我以更清晰的方式來重寫。此外，我提出了一套不同的體驗和觀點，目前，對公司的應用程序用户體驗改進有着很大幫助。</p><h3 id="提高" tabindex="-1">提高 <a class="header-anchor" href="#提高" aria-label="Permalink to “提高”">​</a></h3><p>工程師的角色不僅僅是編碼，而是廣泛的技能。 我仍然處於旅程的起點，在掌握它的道路上，我想着重於以下幾點：</p><ul><li>交流：因為英文不是我的母語，所以有的時候我需要努力傳達我的想法，這在我工作中是至關重要的。我可以通過寫作，閲讀和交談來解決這個問題。</li><li>提有建設性的反饋意見：我想給同事有意義的反饋，這樣我們一起共同發展。</li><li>為我的成就感到驕傲：我需要創建一個列表來跟蹤各種成就，無論大小，或整體進步，所以當我掙扎時我可以回顧並感覺良好。</li><li>不要着迷於不知道的事情：當有很多新事物出現時很難做到都知道，所以只關注必須的，及手頭項目需要的東西，這非常重要的。</li><li>多和同事分享知識：我是初級的並不意味着沒有可以分享的！我需要持續分享我感興趣的的文章及討論話題。我知道同事們會感激我的。</li><li>耐心和持續學習：和現在一樣的保持不斷學習，但對自己要有更多耐心。</li><li>自我保健：隨時注意休息，不要為難自己。 放鬆也富有成效。</li></ul><hr>',24)),i("p",null,[r[20]||(r[20]=a("via: ",-1)),e(d,{href:"https://proandroiddev.com/a-year-as-android-engineer-55e2a428dfc8"},{default:t(()=>[...r[19]||(r[19]=[a("https://proandroiddev.com/a-year-as-android-engineer-55e2a428dfc8",-1)])]),_:1})]),i("p",null,[r[24]||(r[24]=a("作者：",-1)),e(d,{href:"https://proandroiddev.com/@laramartin"},{default:t(()=>[...r[21]||(r[21]=[a("Lara Martín",-1)])]),_:1}),r[25]||(r[25]=a(" 譯者：",-1)),e(d,{href:"https://github.com/runningwater"},{default:t(()=>[...r[22]||(r[22]=[a("runningwater",-1)])]),_:1}),r[26]||(r[26]=a(" 校對：",-1)),e(d,{href:"https://github.com/wxy"},{default:t(()=>[...r[23]||(r[23]=[a("wxy",-1)])]),_:1})]),i("p",null,[r[29]||(r[29]=a("本文由 ",-1)),e(d,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...r[27]||(r[27]=[a("LCTT",-1)])]),_:1}),r[30]||(r[30]=a(" 原創編譯，",-1)),e(d,{href:"https://linux.cn/"},{default:t(()=>[...r[28]||(r[28]=[a("Linux中國",-1)])]),_:1}),r[31]||(r[31]=a(" 榮譽推出",-1))])])}const P=o(f,[["render",m]]);export{k as __pageData,P as default};
